namespace sv_de6352d0743d464e9ef5845dec075388.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// Interactive components subscribe to <see cref="OnChanged"/> to re-render
/// when any component mutates the theme.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever <see cref="Theme"/> or <see cref="AccentColor"/> changes.
    /// Subscribers should call <c>InvokeAsync(StateHasChanged)</c>.
    /// </summary>
    public event Action? OnChanged;

    /// <summary>
    /// Apply both values at once, firing a single notification.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        Services.ThemeMode.Light  => "☀️",
        Services.ThemeMode.Dark   => "🌙",
        _                        => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px; border-color: @ThemeSvc.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <button class="btn @(ThemeSvc.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    style="--bs-btn-active-bg: @ThemeSvc.AccentColor; --bs-btn-bg: @(ThemeSvc.Theme == mode ? ThemeSvc.AccentColor : "transparent");"
                    @onclick="() => ThemeSvc.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@ThemeSvc.AccentColor"
               @onchange="OnColorChanged" />
        <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
    </div>

    <p class="text-muted mt-2 mb-0">
        Changes are applied instantly across all components.
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChanged += HandleThemeChanged;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChanged -= HandleThemeChanged;
    }
}

